#include "stdlib/lapack/base/dlantr.h"
#include <stdio.h>

int main( void ) {
	const double A[] = { 2.0, -3.0, 4.0, 0.0, 5.0, -6.0 };
	double work[ 2 ];
	double v;

	v = API_SUFFIX(c_dlantr)( LAPACK_ROW_MAJOR, 'I', LAPACK_UPPER_TRIANGLE, LAPACK_NON_UNIT_DIAGONAL, 2, 3, A, 3, work );
	printf( "infinity norm: %f\n", v );
	v = API_SUFFIX(c_dlantr)( LAPACK_ROW_MAJOR, 'F', LAPACK_UPPER_TRIANGLE, LAPACK_NON_UNIT_DIAGONAL, 2, 3, A, 3, NULL );
	printf( "Frobenius norm: %f\n", v );
	return 0;
}
